I have often come across the need to have a generic parameter-object persisted into the viewstate in a base class. public abstract class BaseListControl<ListType,KeyType,ParameterType>
                 : UserControl 
                 where ListType : BaseListType
                 && ParameterType : BaseParameterType, new
{

    private const string viewStateFilterKey = "FilterKey";

    protected ParameterType Filters
    {
        get
        {
            if (ViewState[viewStateFilterKey] == null)
                ViewState[viewStateFilterKey]= new ParameterType();

            return ViewState[viewStateFilterKey] as ParameterType;
        }
        set
        {
            ViewState[viewStateFilterKey] = value;
        }
    }

} Usage: private void SomeEventHappened(object sender, EventArgs e)
{
    Filters.SomeValue = SomeControl.SelectedValue;
}

private void TimeToFetchSomeData()
{
    GridView.DataSource = Repository.GetList(Filters);
} This little trick with the "where ParameterType : BaseParameterType, new" is what makes it really work. With this property in my baseclass, I can automate handling of paging, setting filter values to filter a gridview, make sorting really easy, etc. I am really just saying that generics can be an enormously powerful beast in the wrong hands.

