Take advantage of the standard char_traits . Recall that a std::string is in fact a typedef for std::basic_string<char> , or more explicitly, std::basic_string<char, std::char_traits<char> > . The char_traits type describes how characters compare, how they copy, how they cast etc. All you need to do is typedef a new string over basic_string , and provide it with your own custom char_traits that compare case insensitively. struct ci_char_traits : public char_traits<char> {
    static bool eq(char c1, char c2) { return toupper(c1) == toupper(c2); }
    static bool ne(char c1, char c2) { return toupper(c1) != toupper(c2); }
    static bool lt(char c1, char c2) { return toupper(c1) <  toupper(c2); }
    static int compare(const char* s1, const char* s2, size_t n) {
        while( n-- != 0 ) {
            if( toupper(*s1) < toupper(*s2) ) return -1;
            if( toupper(*s1) > toupper(*s2) ) return 1;
            ++s1; ++s2;
        }
        return 0;
    }
    static const char* find(const char* s, int n, char a) {
        while( n-- > 0 && toupper(*s) != toupper(a) ) {
            ++s;
        }
        return s;
    }
};

